python3 << 'EOF'
from openpyxl import load_workbook

def get_country(desc):
    if not desc:
        return None
    country = desc.split(':')[0].strip()
    if 'Czechia' in country:
        return 'Czechia'
    if 'Kyrgyz' in country:
        return 'Kyrgyz Republic'
    return country

wb = load_workbook('/root/output/rar_result.xlsx')
ws_res = wb['Total Reserves']

print("=== Total Reserves sheet - Countries with 2025 data ===")
reserves_countries = {}
for col in range(2, ws_res.max_column + 1):
    desc = ws_res.cell(row=1, column=col).value
    val_2025 = ws_res.cell(row=18, column=col).value  # Row 18 is 2025
    if desc and val_2025 is not None and desc != '.DESC':
        country = get_country(desc)
        if country:
            reserves_countries[country] = {'col': col, 'value': val_2025}
            print(f"{country}: {val_2025} (col {col})")

print(f"\nTotal countries with 2025 Total Reserves: {len(reserves_countries)}")

# Countries we have in STEP 2
step2_countries = ['Belarus', 'Georgia', 'Moldova', 'Ukraine', 'Uzbekistan', 'Czechia', 'Latvia', 'Lithuania', 'Slovakia']

# Find which countries have both gold reserves and total reserves in 2025
print("\n=== Countries with both gold reserves and total reserves 2025 data ===")
matching_countries = []
for country in step2_countries:
    if country in reserves_countries:
        print(f"{country}: Total Reserves = {reserves_countries[country]['value']} (col {reserves_countries[country]['col']})")
        matching_countries.append((country, reserves_countries[country]['col']))
    else:
        print(f"{country}: NO 2025 total reserves data - EXCLUDED")

print(f"\nCountries for STEP 3: {len(matching_countries)}")
for c, col in matching_countries:
    print(f"  {c} (Total Reserves col {col})")
